import java.io.*;
import java.util.*;

public class E {
    public static void main(String[] args) throws Exception {
        new E().calculate();
    }

    public void calculate() throws Exception {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int l = sc.nextInt();
        int r = sc.nextInt();

        if (n % 2 == 1 && m % 2 == 1) {
            long res = pow(pow(r - l + 1, n), m);
            pw.println(res);
            pw.flush();
            return;
        }

        int evenCount = r / 2 - (l + 1) / 2 + 1;
        int oddCount = (r - l + 1) - evenCount;

        long[][] matrix = {{evenCount, oddCount}, {oddCount, evenCount}};
        matrix = matrixPower(matrix, n);
        matrix = matrixPower(matrix, m);
        pw.println(matrix[0][0]);
        pw.flush();
    }

    final int MOD = 998244353;

    private long[][] matrixPower(long[][] base, int exp) {
        if (exp == 1) return base;
        long[][] half = matrixPower(base, exp / 2);
        long[][] result = multiplyMatrices(half, half);
        if (exp % 2 == 1) {
            result = multiplyMatrices(result, base);
        }
        return result;
    }

    private long[][] multiplyMatrices(long[][] a, long[][] b) {
        int rA = a.length, cA = a[0].length;
        int rB = b.length, cB = b[0].length;
        long[][] res = new long[rA][cB];
        for (int i = 0; i < rA; i++) {
            for (int j = 0; j < cB; j++) {
                long sum = 0;
                for (int k = 0; k < cA; k++) {
                    sum += a[i][k] * b[k][j];
                }
                res[i][j] = sum % MOD;
            }
        }
        return res;
    }

    private long pow(long base, int exp) {
        long result = 1;
        long cur = base;
        int e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * cur) % MOD;
            }
            cur = (cur * cur) % MOD;
            e >>= 1;
        }
        return result;
    }
}
